// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRoboto = makeLoadFont('Roboto');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: robotoFamily } = loadRoboto();



export type CalendarOverlayProps = Record<string, any>;

const CalendarOverlay: React.FC<CalendarOverlayProps> = ({
  backgroundColor = "#0b193d",
  transparentBackground = false,
  durationInSeconds = 10,
  textColor = "#ffffff",
  lineColor = "#ffffff",
  timelineItems = [
    { date: "JAN 2024", color: "#7970c6" },
    { date: "APR 2024", color: "#61b089" },
    { date: "JUL 2024", color: "#f9bc3e" },
    { date: "OCT 2024", color: "#f47844" },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout Dimensions
  const itemWidth = 200 * s;
  const gap = 150 * s;
  const centerY = height / 2;

  // Total container width of the timeline
  const totalWidth = timelineItems.length * itemWidth + (timelineItems.length - 1) * gap;

  // Animation Timing Logic for the "Scrolling By" effect
  const totalFrames = durationInSeconds * fps;
  const enterDuration = Math.min(fps * 1.5, totalFrames * 0.2);
  const exitDuration = Math.min(fps * 1.5, totalFrames * 0.2);
  
  const panAmount = 200 * s; // Distance it drifts while on screen
  const centerStartX = (width - totalWidth) / 2 + panAmount / 2;
  const centerEndX = (width - totalWidth) / 2 - panAmount / 2;

  // Calculate container horizontal position
  let translateX = 0;
  if (frame < enterDuration) {
    const progress = spring({ frame, fps, config: { damping: 14, mass: 1.2 } });
    translateX = interpolate(progress, [0, 1], [width, centerStartX]);
  } else if (frame > totalFrames - exitDuration) {
    const progress = spring({ frame: frame - (totalFrames - exitDuration), fps, config: { damping: 14, mass: 1.2 } });
    translateX = interpolate(progress, [0, 1], [centerEndX, -totalWidth - (200 * s)]);
  } else {
    const progress = (frame - enterDuration) / (totalFrames - enterDuration - exitDuration);
    translateX = interpolate(progress, [0, 1], [centerStartX, centerEndX]);
  }

  // Arrows fade in during hold, out during exit
  const arrowOpacity = interpolate(
    frame,
    [enterDuration * 0.5, enterDuration, totalFrames - exitDuration, totalFrames - exitDuration * 0.5],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Main track line drawing progress
  const isLineStarted = frame >= 5;
  const lineProgress = spring({
    frame: frame - 5,
    fps,
    config: { damping: 18, mass: 1 },
  });

  const startTrackX = itemWidth / 2;
  const endTrackX = totalWidth - itemWidth / 2;
  const currentLineX = isLineStarted
    ? interpolate(lineProgress, [0, 1], [startTrackX, endTrackX], { extrapolateRight: "clamp" })
    : startTrackX;

  const startRevealFrame = 10;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: robotoFamily }}>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          height: "100%",
          width: "100%",
          position: "relative",
          transition: "none",
        }}
      >
        {/* Left Arrow */}
        <svg
          width={44 * s}
          height={88 * s}
          viewBox="0 0 44 88"
          style={{
            position: "absolute",
            left: `${100 * s}px`,
            opacity: arrowOpacity,
            zIndex: 10,
            transition: "none",
          }}
        >
          <path
            d="M 38 12 L 12 44 L 38 76"
            fill="none"
            stroke="#ffffff"
            strokeWidth={8 * s}
            strokeLinecap="round"
            strokeLinejoin="round"
            style={{ transition: "none" }}
          />
        </svg>

        {/* Carousel Container */}
        <div
          style={{
            position: "absolute",
            display: "flex",
            width: `${totalWidth}px`,
            height: `${height}px`,
            left: 0,
            transform: `translateX(${translateX}px)`,
            transition: "none",
          }}
        >
          {/* Background and Connector Lines SVG Layer */}
          <svg
            width={totalWidth}
            height={height}
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              pointerEvents: "none",
              transition: "none",
            }}
          >
            {/* Main static timeline track (faint) */}
            <path
              d={`M ${startTrackX} ${centerY} L ${endTrackX} ${centerY}`}
              fill="none"
              stroke={lineColor}
              strokeWidth={6 * s}
              strokeLinecap="round"
              opacity={0.15}
              style={{ transition: "none" }}
            />

            {/* Active drawing track line */}
            <path
              d={`M ${startTrackX} ${centerY} L ${currentLineX} ${centerY}`}
              fill="none"
              stroke={lineColor}
              strokeWidth={6 * s}
              strokeLinecap="round"
              style={{ transition: "none" }}
            />

            {/* Glow tracker dot at the tip of the track drawing */}
            {isLineStarted && (
              <circle
                cx={currentLineX}
                cy={centerY}
                r={8 * s}
                fill="#ffffff"
                style={{
                  filter: `drop-shadow(0 0 ${8 * s}px ${lineColor})`,
                  transition: "none",
                }}
              />
            )}

            {/* Vertical connector lines */}
            {timelineItems.map((item, i) => {
              const nodeX = i * (itemWidth + gap) + itemWidth / 2;
              const targetY = i % 2 === 0 ? centerY - 100 * s : centerY + 100 * s;
              const nodeStartFrame = startRevealFrame + i * 12;
              const connStartFrame = nodeStartFrame + 6;
              const isConnStarted = frame >= connStartFrame;

              const connProgress = spring({
                frame: frame - connStartFrame,
                fps,
                config: { damping: 15, mass: 0.8 },
              });
              const clampedConnProgress = isConnStarted ? Math.max(0, Math.min(1, connProgress)) : 0;
              const currentConnY = interpolate(clampedConnProgress, [0, 1], [centerY, targetY]);

              return (
                <path
                  key={i}
                  d={`M ${nodeX} ${centerY} L ${nodeX} ${currentConnY}`}
                  fill="none"
                  stroke={item.color}
                  strokeWidth={4 * s}
                  strokeDasharray={`${6 * s} ${4 * s}`}
                  style={{ transition: "none", opacity: isConnStarted ? 1 : 0 }}
                />
              );
            })}
          </svg>

          {/* Interactive Timeline Nodes and Dates */}
          {timelineItems.map((item, i) => {
            const nodeX = i * (itemWidth + gap) + itemWidth / 2;
            const nodeStartFrame = startRevealFrame + i * 12;
            const dateStartFrame = nodeStartFrame + 12;

            const isNodeVisible = frame >= nodeStartFrame;
            const isDateVisible = frame >= dateStartFrame;

            // Animations
            const nodeScale = spring({
              frame: frame - nodeStartFrame,
              fps,
              config: { damping: 12, mass: 0.6 },
            });
            const clampedNodeScale = isNodeVisible ? Math.max(0, nodeScale) : 0;

            const dateScale = spring({
              frame: frame - dateStartFrame,
              fps,
              config: { damping: 14, mass: 0.8 },
            });
            const clampedDateScale = isDateVisible ? Math.max(0, dateScale) : 0;

            const isAbove = i % 2 === 0;
            const dateTop = isAbove ? centerY - 150 * s : centerY + 110 * s;

            return (
              <React.Fragment key={i}>
                {/* Milestone Node */}
                <div
                  style={{
                    position: "absolute",
                    left: nodeX - 16 * s,
                    top: centerY - 16 * s,
                    width: 32 * s,
                    height: 32 * s,
                    borderRadius: "50%",
                    backgroundColor: "#ffffff",
                    border: `${6 * s}px solid ${item.color}`,
                    boxShadow: `0 0 ${16 * s}px ${item.color}`,
                    transform: `scale(${clampedNodeScale})`,
                    transformOrigin: "center",
                    opacity: isNodeVisible ? 1 : 0,
                    transition: "none",
                    zIndex: 5,
                  }}
                />

                {/* Date Number Display */}
                <div
                  style={{
                    position: "absolute",
                    left: nodeX - 150 * s,
                    top: dateTop,
                    width: 300 * s,
                    textAlign: "center",
                    color: textColor,
                    fontSize: `${32 * s}px`,
                    fontWeight: 800,
                    letterSpacing: `${2 * s}px`,
                    transform: `scale(${clampedDateScale}) translateY(${interpolate(
                      clampedDateScale,
                      [0, 1],
                      [isAbove ? 20 * s : -20 * s, 0]
                    )}px)`,
                    opacity: clampedDateScale,
                    transition: "none",
                    zIndex: 4,
                  }}
                >
                  {item.date}
                </div>
              </React.Fragment>
            );
          })}
        </div>

        {/* Right Arrow */}
        <svg
          width={44 * s}
          height={88 * s}
          viewBox="0 0 44 88"
          style={{
            position: "absolute",
            right: `${100 * s}px`,
            opacity: arrowOpacity,
            zIndex: 10,
            transition: "none",
          }}
        >
          <path
            d="M 6 12 L 32 44 L 6 76"
            fill="none"
            stroke="#ffffff"
            strokeWidth={8 * s}
            strokeLinecap="round"
            strokeLinejoin="round"
            style={{ transition: "none" }}
          />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default CalendarOverlay;